shellCommands.command:
/bin/bash -lc "node --input-type=module <<'NODE'
const cases = [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
  ['/products/vase', 'Stone vase', 'USD 80.00', 'Brass lamp'],
]
for (const [path, name, price, related] of cases) {
  const start = performance.now()
  const response = await fetch("'`http://localhost:3000${path}`)
  const chunks = []
  for await (const chunk of response.body) chunks.push({ at: Math.round(performance.now() - start), html: new TextDecoder().decode(chunk) })
  const html = chunks.map((chunk) => chunk.html).join('"'')
  const outcome = { path, status: response.status, chunks: chunks.length, firstChunkMs: chunks[0]?.at, shell: chunks[0]?.html.includes('Signal Shop collection'), productFallback: chunks[0]?.html.includes('Loading product details'), relatedFallback: html.includes('Loading related products'), name: html.includes(name), price: html.includes(price), related: html.includes(related) }
  console.log(JSON.stringify(outcome))
}
NODE"
